import sys; sys.path.insert(0,'/home/claude/scripts')
from facts_lib import save
N="تعليمات منح درجة البكالوريوس في تخصص دكتور في الطب"
save("0216",N,[
("rule",[7],"المادة 16","ينتقل الطالب من سنة دراسية إلى التي تليها إذا نجح في كل مساق علمي درسه في تلك السنة وحصل على معدل سنوي 2.00 فأكثر. ولا يرفع الطالب إلا في نهاية السنة الدراسية وبعد نجاحه في جميع المساقات العلمية للسنوات السابقة لمستواه.",
 "ما شروط انتقال طالب الطب من سنة دراسية إلى التي تليها؟","هل يرفع طالب الطب من سنة قبل نهاية السنة الدراسية؟","شو لازم أحقق عشان أنتقل للسنة اللي بعدها بالطب؟"),
("rule",[7],"المادة 17 (أ-1)","يشترط لانتقال طلبة السنة الأولى إلى الثانية النجاح في جميع المساقات العلمية المرفعة وهي: تح104، تح108، ك108، ف104، ط114، ط115، ط132، ط173، ط122، ط183، ط133، والحصول على معدل سنوي 2.00 فأكثر.",
 "ما المساقات العلمية المرفعة التي يشترط النجاح فيها للانتقال من السنة الأولى إلى الثانية في الطب؟","ما شروط انتقال طلبة السنة الأولى في الطب إلى السنة الثانية؟","أي مواد لازم أنجح فيها بسنة أولى طب عشان أنتقل؟"),
("rule",[7],"المادة 17 (أ-2، أ-3)","إذا رسب طالب السنة الأولى في مساق أو مساقين علميين من المرفعة يحق له امتحان إكمال في مساق أو مساقين على الأكثر قبل بدء الفصل الأول من العام التالي في موعد يحدده عميد الكلية التي تطرح المساق. وإذا كان ناجحاً في جميع المساقات العلمية وحاصلاً على معدل أقل من 2.00 يحق له امتحان إكمال في مساق أو مساقين يختارهما، ويثبت له الرمز الجديد كما هو.",
 "متى يحق لطالب السنة الأولى في الطب التقدم لامتحان إكمال؟","ماذا يحدث إذا نجح الطالب في كل مساقات السنة الأولى وكان معدله أقل من 2.00؟","رسبت بمادتين بسنة أولى طب، بقدر أقدم إكمال؟"),
("rule",[7],"المادة 17 (أ-4، أ-5)","يجرى امتحان غير المكتمل للمساقات الصيفية قبل امتحان الإكمال، وتعقد امتحانات الإكمال قبل بداية الفصل الأول من السنة التالية وتنتهي في موعد أقصاه نهاية الأسبوع الأول من الفصل الأول، وتثبت علامة الإكمال خلال أسبوع على الأكثر من انتهاء فترة الإكمال. وإذا كان لدى الطالب غير مكتمل في مساق أو تعديل علامة لمساق علمي مرفع فيسمح له بامتحان الإكمال إذا حقق شروطه باستثناء ذلك المساق.",
 "متى تعقد امتحانات الإكمال لطلبة السنة الأولى في الطب وخلال كم تثبت العلامة؟","هل يسمح بامتحان الإكمال لمن لديه غير مكتمل أو تعديل علامة في مساق مرفع؟","متى بتصير امتحانات الإكمال بالطب؟"),
("rule",[7],"المادة 17 (ب)","يعتبر الطالب راسباً في السنة الأولى إذا رسب في أكثر من مساقين علميين من المساقات المرفعة، أو رسب بعد امتحان الإكمال في أي مساق، أو لم يحصل على معدل سنوي 2.00 فأكثر بعد امتحان الإكمال.",
 "متى يعتبر طالب الطب راسباً في السنة الأولى؟","هل أرسب بالسنة الأولى لو رسبت بعد الإكمال بمساق واحد؟","شو شروط الرسوب بالسنة الأولى طب؟"),
("rule",[7],"المادة 17 (ج، د)","إذا رسب الطالب في السنة الأولى يسمح له بإعادتها لمرة واحدة فقط، ويعيد جميع المساقات العلمية التي رسب بها، ويعيد مساقات كلية الطب (ط173، ط114، ط115، ط122، ط132، ط183، ط133) التي حصل فيها على علامة أقل من (ج-) ويدخل الرمز الجديد في المعدل السنوي. ولا يجوز إعادة المساقات المرفعة الحاصل فيها على (ج-) فأكثر. ويجوز إعادة المساقات الناجح بها (ك108، ف104، تح104، تح108) ويحسب الرمز الأعلى ويجوز الانسحاب منها بدون ترصيد الرسوم.",
 "كم مرة يسمح لطالب الطب بإعادة السنة الأولى وأي مساقات يعيدها؟","هل يجوز لطالب السنة الأولى إعادة مساق ناجح به كالكيمياء العامة والفيزياء الطبية؟","رسبت سنة أولى طب، شو لازم أعيد؟"),
("rule",[7],"المادة 17 (هـ)","تحتسب علامة امتحان الإكمال بدلاً من العلامة النهائية المستحقة للمساق العلمي.",
 "كيف تحتسب علامة امتحان الإكمال في المساق العلمي بالطب؟","هل تحل علامة الإكمال محل العلامة النهائية للمساق؟","علامة الإكمال بتحل مكان علامة المساق؟"),
("rule",[8],"المادة 18 (أ-1، أ-2)","يشترط لانتقال طلبة السنوات الثانية إلى السادسة النجاح في جميع مساقات السنة حسب الخطة (باستثناء متطلبات الجامعة) ومعدل سنوي 2.00 فأكثر. وإذا رسب الطالب في مساق أو مساقين على الأكثر من مساقات السنة الثانية أو الثالثة (بغض النظر عن الساعات) يحق له امتحان إكمال في المساقات التي رسب بها قبل بدء الفصل التالي من العام الجامعي التالي في موعد يحدده العميد، وإذا رسب بعد الإكمال في أي منها لا ينتقل ويعتبر راسباً في تلك السنة.",
 "ما شروط انتقال طلبة السنتين الثانية والثالثة في الطب وكم مساقاً يحق إكماله؟","ماذا يحدث لطالب السنة الثانية إذا رسب في مساق بعد الإكمال؟","رسبت بمادة بسنة ثانية طب، بقدر أقدم إكمال؟"),
("rule",[8],"المادة 18 (أ-3، أ-4)","إذا رسب الطالب في مساق أو مساقات مجموع ساعاتها 9 ساعات معتمدة فأقل من مساقات السنة الرابعة أو الخامسة يحق له امتحان إكمال فيها، وإذا رسب بعده لا ينتقل ويعتبر راسباً في تلك السنة. وإذا رسب في مساق من مساقات السنة السادسة يحق له امتحان إكمال في المساق بعد إعادة التدريب السريري كاملاً فيه، فإن نجح يعتبر ناجحاً في السادسة وإن رسب يعتبر راسباً.",
 "كم ساعة يحق لطالب السنة الرابعة أو الخامسة الرسوب بها مع امتحان إكمال؟","كيف يتم الإكمال لطالب السنة السادسة الراسب في مساق؟","رسبت بمساق بسنة سادسة طب، شو إجراء الإكمال؟"),
("rule",[8],"المادة 18 (أ-5)","إذا كان الطالب ناجحاً في جميع مساقات السنوات الثانية إلى السادسة وحاصلاً على معدل سنوي أقل من 2.00 يحق له امتحان إكمال في مساق أو مساقين على الأكثر من مساقات الثانية أو الثالثة، ومساقات مجموع ساعاتها 9 ساعات على الأكثر من الرابعة أو الخامسة أو السادسة (بعد إعادة التدريب السريري للسادسة) يختارها من مساقات تلك السنة قبل بدء العام الجامعي التالي. وإذا أخفق في رفع المعدل إلى 2.00 فأكثر لا ينتقل ويعتبر راسباً.",
 "ماذا يفعل طالب الطب الناجح بجميع المساقات ومعدله السنوي أقل من 2.00 في السنوات الثانية إلى السادسة؟","كم مساقاً أو ساعة يختار للإكمال لرفع المعدل السنوي؟","نجحت بكل المواد ومعدلي أقل من 2، شو الحل؟"),
("rule",[8],"المادة 18 (أ-6، أ-7، أ-8، أ-9)","يجرى امتحان غير المكتمل لمساقات الصيفي للسنتين الثانية والثالثة قبل امتحان الإكمال، وتعقد امتحانات الإكمال قبل بداية الفصل الأول من السنة التالية وتنتهي بداية الأسبوع الأول منه وتثبت علامة الإكمال خلال أسبوع. وتجرى امتحانات الإكمال للسنوات الثالثة والرابعة والخامسة قبل بداية الدوام الرسمي للسنة اللاحقة. ويسمح لمن لديه غير مكتمل أو تعديل علامة في مساق علمي بالإكمال إذا حقق الشروط باستثناء ذلك المساق. ويحسب مجموع ساعات المساقات العلمية المتبقية من المستويات السابقة حسب المادتين 24 (ج) و25 (أ-4) ضمن ساعات مستوى الطالب الحالي.",
 "متى تجرى امتحانات الإكمال للسنوات الثالثة والرابعة والخامسة في كلية الطب؟","كيف تحتسب الساعات المتبقية من المستويات السابقة ضمن شروط مستوى الطالب الحالي؟","موعد امتحانات الإكمال للسنة الثالثة والرابعة؟"),
("rule",[8],"المادة 18 (ب)","يعتبر الطالب راسباً في أي سنة من الثانية إلى السادسة إذا رسب في أكثر من مساقين في السنة الثانية أو الثالثة، أو رسب في مساقات عدد ساعاتها أكثر من 9 ساعات معتمدة في الرابعة أو الخامسة أو السادسة، أو لم يحصل على معدل 2.00 فأكثر بعد الإكمال، أو رسب بعد الإكمال في أي مساق.",
 "متى يعتبر طالب الطب راسباً في السنوات الثانية إلى السادسة؟","كم ساعة رسوب في السنة الرابعة تعني الرسوب في السنة؟","شو بخليني أرسب السنة بالطب؟"),
("rule",[8],"المادة 18 (هـ)","إذا رسب الطالب في أي من السنوات الثانية إلى السادسة يعيد دراسة جميع المساقات المقررة لتلك السنة من داخل كلية الطب والحاصل فيها على رمز أقل من (ج-)، وتحسب نقاط الرمز الجديد في المعدل السنوي، ولا يجوز إعادة المساقات العلمية الحاصل فيها على (ج-) فأكثر. وتحسب عند إعادة السنة الرموز الجديدة فقط ويعيد فقط المساقات التي لم يحصل فيها على (ج-) فأكثر (المادة 19).",
 "أي المساقات يعيدها طالب الطب الراسب في سنة من الثانية إلى السادسة؟","هل تحسب علامات السنة القديمة عند إعادة السنة في الطب؟","إذا أعدت السنة بالطب، لازم أعيد كل المواد؟"),
("rule",[8],"المادة 18 (و)","إذا تقدم الطالب لامتحان إكمال يثبت له الرمز الجديد في كشف العلامات: فإذا كان معدله السنوي قبل الإكمال أقل من 2.00 يثبت الرمز الجديد بما لا يتجاوز معدله في تلك السنة 2.00 بعد الإكمال إذا تجاوز معدله ذلك. وإذا كان معدله 2.00 فأكثر يثبت الرمز الجديد على أن يرصد له (ج-) كحد أقصى في ذلك المساق لأغراض احتساب معدله النهائي في السنة حتى لو كان رمز الإكمال أعلى.",
 "ما أقصى رمز يحتسب في المعدل بعد امتحان الإكمال لطالب الطب؟","كيف يؤثر امتحان الإكمال على المعدل السنوي إذا كان المعدل قبله أقل من 2.00؟","نجحت بالإكمال بعلامة عالية، كم بتتحسب بالمعدل؟"),
("rule",[9],"المادة 20 (أ، ب)","يفصل الطالب من تخصص دكتور في الطب إذا لم يستطع اجتياز أي سنة من السنوات الخمس الأولى في مدة سنتين جامعيتين، أو لم يجتز السنة السادسة في ثلاث سنوات جامعية، أو لم يكمل دراسته خلال 9 سنوات، أو رسب بأي 4 سنوات دراسية خلال دراسته. وإذا فصل من الطب وكان فصل سابقاً من تخصص آخر في الجامعة يفصل من الجامعة نهائياً ولا يجوز له العودة، وإنما يتاح له الاستفادة مما ورد في الفقرة (د).",
 "ما حالات الفصل من تخصص دكتور في الطب؟","ماذا يحدث لطالب الطب المفصول وكان قد فصل سابقاً من تخصص آخر في الجامعة؟","شو بيخليني أنفصل من الطب؟"),
("rule",[9],"المادة 20 (ج، د)","تصدر قرارات الفصل من التخصص أو الكلية أو الجامعة عن مجلس العمداء بتنسيب من مجلس الكلية، وتشعر وحدة القبول والتسجيل الطالب إلكترونياً على آخر عنوان له لدى الجامعة. ويستند تحديد البرنامج المتاح للطالب للحصول على السنة الإضافية إلى جدول يربط البرنامج الذي فصل منه (الفئة أ) بالبرنامج المتاح له (الفئة ب) حسب الجنسية والرسوم، وأبناء العاملين المقصودون هم أبناء العاملين في جامعة العلوم والتكنولوجيا الأردنية وجامعة اليرموك ومستشفى الملك المؤسس عبد الله الجامعي.",
 "من يصدر قرارات الفصل وكيف يبلغ الطالب في كلية الطب؟","من هم أبناء العاملين المقصودون في جدول فئات السنة الإضافية؟","كيف بعرفوني بقرار الفصل ومين بقصدوا بأبناء العاملين؟"),
("rule",[9],"المادة 20 (د-2)","يحق للطالب من الفئة (أ) المفصول من الطب أن يستمر في نفس التخصص ضمن الفئة (ب) ويعطى سنة دراسية إضافية لاحقة دون انقطاع، ويجوز التأجيل أو الانسحاب للسنة الإضافية، لإزالة أسباب فصله أو إنهاء متطلبات الدرجة. وإذا لم يتمكن من إزالة الأسباب يفصل من التخصص، ويحق له الاستمرار ضمن الفئة (ب) بسنة إضافية لاحقة. وإذا تمكن يستمر في تخصصه ضمن الفئة (ب)، وفي حال فصله للمرة الثانية يحق له الاستمرار حسب البند (2).",
 "هل يعطى طالب الطب المفصول سنة دراسية إضافية وبأي فئة؟","ماذا يحدث إذا لم يتمكن الطالب من إزالة أسباب فصله خلال السنة الإضافية في الطب؟","انفصلت من الطب، في فرصة أكمل؟"),
],"e",verified="text")
